head.script:
scwin.gVar = {
    "cRef" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > ref]<br/>Secret 컴포넌트의 입력값에 바인딩할 DataCollection 정보를 설정합니다.",
    "validation" : [
        "접근 가능한 DataCollection 의 컬럼을 'data:[DataCollection ID].[Key 또는 Column ID]' 형식으로 설정합니다.",
        "유효하지 않은 값으로 설정 시 바인딩 처리되지 않고 입력창에 빈값이 표시됩니다.",
        "Secret 컴포넌트는 입력값을 마스킹 문자로 표시하지만 바인딩한 DataCollection 에 저장되는 값은 마스킹되지 않은 평문입니다.",
        "DataList 를 바인딩 한 경우 DataList 의 데이터를 선택하지 않으면 입력창에 빈값이 표시됩니다.",
        "데이터를 선택하지 않은 상태에서 입력된 값은 데이터 선택 시 사라집니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출 (gdm_ref, gdl_ref, gdl_ref_list)
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_ref_list 는 label 이 ref 문자열이므로 인덱스로 선택)
    con_ref.setSelectedIndex(1);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 con_ref 에서 선택한 값이 ref 속성으로 적용됩니다\nTarget 재생성 시 gdm_ref.key1 은 dm_data 로 초기화되고 gdl_ref 는 미선택 상태가 됩니다\n[절차] 위 조건 선택 -> Target 재생성 -> 검증 목적에 따라 아래 중 하나를 수행\n - 바인딩 표시 / 무효값 / 평문 저장 : 값 확인 버튼 클릭\n - DataList 미선택 빈값 : ref 를 data:gdl_ref.label 로 재생성 -> 값 확인 -> DataList선택 -> 값 확인 -> DataList미선택 -> 값 확인\n - 미선택 입력값 소멸 : ref 를 data:gdl_ref.label 로 재생성 -> target1 에 직접 타이핑 -> 값 확인 -> DataList선택 -> 값 확인\n[확인] password 라 화면으로 값을 읽을 수 없으므로 결과창의 target1 값과 길이, 입력창 type, 바인딩 데이터 값으로 판정"', '', 'label1');

    // 조건 설정
    scwin.gVar["cRef"] = con_ref.getText();

    // 바인딩 데이터 초기화 (dataMap 은 초기값, DataList 는 미선택 상태)
    gdm_ref.set("key1", "dm_data");
    gdl_ref.setRowPosition(-1);

    let properties = {
        ref : scwin.gVar["cRef"],
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList);

    // 헬퍼가 넣은 초기값을 지워 ref 바인딩 결과만 입력창에 남긴다
    if (scwin.gVar["cRef"] !== "") {
        target1.setValue("");

        if (scwin.gVar["cRef"] === "data:gdm_ref.key1")
            gdm_ref.set("key1", "dm_data");
    }

    // DataList 바인딩일 때만 선택 조작 버튼 사용
    let bList = (scwin.gVar["cRef"] === "data:gdl_ref.label");
    btn_selectRow.setDisabled(!bList);
    btn_deselectRow.setDisabled(!bList);
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 바인딩 된 DataCollection 에 저장된 값 (바인딩이 없으면 빈 문자열)
scwin.fn_bound = function () {
    let cRef = scwin.gVar["cRef"];

    if (cRef === "data:gdm_ref.key1")
        return " / 바인딩 데이터 값 : " + gdm_ref.get("key1");

    if (cRef === "data:gdl_ref.label") {
        let nRow = gdl_ref.getRowPosition();
        return " / 바인딩 데이터 값 : " + ((nRow < 0) ? "선택된 행 없음" : gdl_ref.getCellData(nRow, "label"));
    }

    return "";
}



// 입력창 표시 상태와 바인딩 데이터 값 확인 - validation 1, 2, 3, 4, 5 판정 출력
scwin.btn_getValue_onclick = function (e) {
    let strValue = target1.getValue() || "";

    wf_body_bottom.getObj("scwin").setReturnValue("ref " + scwin.fn_disp(scwin.gVar["cRef"]) + " -> target1 값 : " + strValue + " (" + strValue.length + "자) / 입력창 type : " + target1.render.type + scwin.fn_bound());
}



// DataList 데이터 선택 (validation 4, 5 발동 수단)
scwin.btn_selectRow_onclick = function (e) {
    gdl_ref.setRowPosition(1);
}



// DataList 데이터 미선택 (validation 4 발동 수단)
scwin.btn_deselectRow_onclick = function (e) {
    gdl_ref.setRowPosition(-1);
}
